pub type Thermostat = {
  current_temp: Float64;
  target_temp: Float64;
}
  invariant: self.current_temp >= -50.0;
  invariant: self.current_temp <= 150.0;

impl Thermostat {
  fn set_target(self: &mut Self, temp: Float64)
    requires: temp >= -50.0;
    requires: temp <= 150.0;
    ensures: self.target_temp == temp;
  { self.target_temp = temp; }

  fn get_current(self: &Self) -> Float64 {
    return self.current_temp;
  }

  fn needs_heating(self: &Self) -> Bool {
    return self.current_temp < self.target_temp;
  }
}

fn main() -> Int {
  var t = Thermostat{ current_temp: 20.0, target_temp: 20.0 };
  t.set_target(22.0);
  if t.needs_heating() { return 1; }
  return 0;
}
